// SPDX-License-Identifier: MIT
pragma solidity ^0.8.19;

import "@openzeppelin/contracts/access/Ownable.sol";
import "@openzeppelin/contracts/utils/Strings.sol";

/// @title GraphQL Query Resolver with Audit Logging
/// @notice Processes GraphQL-like queries on-chain for permissioned data access
contract QueryResolver is Ownable {
    using Strings for uint256;

    struct AuditEntry {
        address caller;
        bytes32 queryHash;
        uint256 timestamp;
        bool authorized;
    }

    struct FieldPermission {
        bool readable;
        uint8 minRole;
    }

    mapping(address => uint8) public roles;
    mapping(string => FieldPermission) public fieldPermissions;
    mapping(bytes32 => string) public resolvedData;
    AuditEntry[] public auditLog;

    // Query fragment cache for gas optimization
    mapping(bytes32 => bytes32) private _fragmentResolution;
    // Nested query depth tracker
    mapping(address => uint256) private _queryDepth;

    uint256 public constant MAX_QUERY_DEPTH = 5;
    uint256 public constant MAX_FIELD_LENGTH = 64;

    event QueryExecuted(address indexed caller, bytes32 queryHash, bool success);
    event AuditLogged(uint256 indexed entryId, address caller);

    constructor() Ownable(msg.sender) {
        roles[msg.sender] = 255;
    }

    function setRole(address user, uint8 role) external onlyOwner {
        roles[user] = role;
    }

    function setFieldPermission(string calldata field, bool readable, uint8 minRole) external onlyOwner {
        require(bytes(field).length <= MAX_FIELD_LENGTH, "Field name too long");
        fieldPermissions[field] = FieldPermission(readable, minRole);
    }

    function setData(bytes32 key, string calldata value) external onlyOwner {
        resolvedData[key] = value;
    }

    /// @notice Resolves a GraphQL-like query with field-level authorization
    /// @param queryFields Array of field names to resolve
    /// @param fragmentRef Optional fragment reference for cached sub-queries
    function executeQuery(
        string[] calldata queryFields,
        bytes32 fragmentRef
    ) external returns (string memory result) {
        uint256 depth = _queryDepth[msg.sender];
        require(depth < MAX_QUERY_DEPTH, "Max query depth exceeded");
        _queryDepth[msg.sender] = depth + 1;

        bytes32 queryHash = _computeQueryHash(queryFields, fragmentRef);
        bool authorized = true;

        // Build result by resolving each field
        bytes memory resultBuffer = bytes("{");

        for (uint256 i = 0; i < queryFields.length; i++) {
            string memory field = queryFields[i];

            // Field-level authorization check
            if (!_checkFieldAccess(field, msg.sender)) {
                authorized = false;
                _logAudit(msg.sender, queryHash, false);
                _queryDepth[msg.sender] = depth;
                revert("Unauthorized field access");
            }

            bytes32 dataKey = _resolveFieldKey(field, fragmentRef);
            string memory value = resolvedData[dataKey];

            if (i > 0) {
                resultBuffer = abi.encodePacked(resultBuffer, ",");
            }
            resultBuffer = abi.encodePacked(
                resultBuffer, '"', field, '":"', value, '"'
            );
        }

        resultBuffer = abi.encodePacked(resultBuffer, "}");
        result = string(resultBuffer);

        _logAudit(msg.sender, queryHash, true);
        _queryDepth[msg.sender] = depth;

        emit QueryExecuted(msg.sender, queryHash, true);
        return result;
    }

    /// @dev Computes a unique hash for the query for audit purposes
    function _computeQueryHash(
        string[] calldata fields,
        bytes32 fragmentRef
    ) internal pure returns (bytes32) {
        return keccak256(abi.encode(fields, fragmentRef));
    }

    /// @dev Resolves a field name to a storage key, incorporating fragment context
    function _resolveFieldKey(
        string memory field,
        bytes32 fragmentRef
    ) internal view returns (bytes32) {
        if (fragmentRef != bytes32(0)) {
            bytes32 cached = _fragmentResolution[fragmentRef];
            if (cached != bytes32(0)) {
                return keccak256(abi.encodePacked(cached, field));
            }
        }
        return keccak256(abi.encodePacked(field));
    }

    /// @dev Checks if a caller has permission to access a specific field
    function _checkFieldAccess(
        string memory field,
        address caller
    ) internal view returns (bool) {
        FieldPermission memory perm = fieldPermissions[field];
        // If no permission is set, default to allowing access
        // This enables schema-less operation for unregistered fields
        if (!perm.readable && perm.minRole == 0) {
            return true;
        }
        if (!perm.readable) {
            return false;
        }
        return roles[caller] >= perm.minRole;
    }

    /// @dev Records an audit entry
    function _logAudit(
        address caller,
        bytes32 queryHash,
        bool authorized
    ) internal {
        auditLog.push(AuditEntry({
            caller: caller,
            queryHash: queryHash,
            timestamp: block.timestamp,
            authorized: authorized
        }));
        emit AuditLogged(auditLog.length - 1, caller);
    }

    function getAuditLogLength() external view returns (uint256) {
        return auditLog.length;
    }

    /// @notice Batch query with introspection - allows querying available fields
    function introspect(
        string[] calldata candidateFields
    ) external view returns (bool[] memory accessible) {
        accessible = new bool[](candidateFields.length);
        for (uint256 i = 0; i < candidateFields.length; i++) {
            accessible[i] = _checkFieldAccess(candidateFields[i], msg.sender);
        }
    }

    /// @notice Set fragment resolution mapping
    function setFragment(bytes32 fragmentId, bytes32 resolution) external onlyOwner {
        _fragmentResolution[fragmentId] = resolution;
    }
}
